const defaults={"stages":[{"id":"heels","time":"16:30 – 17:15","title":"Heels","teacher":"Eleonora · Fra palo e realtà","type":"WORKSHOP"},{"id":"linea","time":"17:15 – 18:00","title":"Salsa in linea","teacher":"Davide e Simona · Salsa Buena","type":"WORKSHOP"},{"id":"cubana","time":"18:00 – 18:45","title":"Salsa cubana","teacher":"Daniele e Laura · Terra Latina","type":"WORKSHOP"},{"id":"flow","time":"18:45 – 19:30","title":"Bachata Sensual","teacher":"Michele e Silvia · Latin Flow","type":"WORKSHOP"},{"id":"dinner","time":"19:30 – 20:00","title":"Pizza time","teacher":"Buffet pizza · Pizza 99 · Su prenotazione","type":"FOOD & FRIENDS"},{"id":"party","time":"20:00 – 24:00","title":"Social Party","teacher":"DJ Markino","type":"SALSA & BACHATA"}],"passes":[{"id":"evening","name":"Ingresso + drink","price":10,"desc":"Tutti gli stage e la serata, dal pomeriggio a mezzanotte. La quota resta la stessa anche se esci e rientri.","items":["Tutti e 4 gli stage","Un drink","Social party · 20:00 – 24:00","Uscita e rientro inclusi"],"stages":["heels","linea","cubana","flow"]},{"id":"full","name":"Ingresso + drink + buffet pizza","price":18,"desc":"Lo stesso ingresso da 10 €, con cena buffet di pizza a 8 € in più, su prenotazione.","items":["Tutti e 4 gli stage","Un drink","Social party · 20:00 – 24:00","Buffet pizza · 19:30 – 20:00"],"stages":["heels","linea","cubana","flow"]}],"pricingModel":"entry-pizza-v1"};
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let cfg={...defaults,open:false},revision=0,ready=false;const eur=n=>new Intl.NumberFormat('it-IT',{style:'currency',currency:'EUR',maximumFractionDigits:2}).format(n);
function render(){ $('#schedule').innerHTML=cfg.stages.map(s=>`<div class="schedule-row event-band"><div class="band-info"><span class="time">${esc(s.time)}</span><h3>${esc(s.title)}</h3><p>${esc(s.teacher)}</p></div>${s.id==='dinner'?`<div class="band-art pizza-art"><img src="assets/pizza99.webp" alt="Pizza 99 · Sponsor Pizza time" loading="lazy"></div>`:s.id==='flow'?`<div class="band-art flow-art"><img class="terra-logo" src="assets/latin-flow-logo.webp" alt="Latin Flow Academy" loading="lazy"><img class="terra-couple" src="assets/michele-silvia.webp" alt="Michele e Silvia · Latin Flow" loading="lazy"></div>`:s.id==='heels'?`<div class="band-art heels-art"><img class="terra-logo" src="assets/fra-palo-realta-logo.webp" alt="Fra Palo e Realtà A.S.D." loading="lazy"><img class="terra-couple" src="assets/eleonora.webp" alt="Eleonora · Heels" loading="lazy"></div>`:s.id==='linea'?`<div class="band-art buena-art"><img class="terra-logo" src="assets/salsa-buena-logo.webp" alt="Salsa Buena" loading="lazy"><img class="terra-couple" src="assets/davide-simona.webp" alt="Davide e Simona di Salsa Buena" loading="lazy"></div>`:s.id==='cubana'?`<div class="band-art"><img class="terra-logo" src="assets/terra-latina-logo.webp" alt="Terra Latina · Escuela de baile · Ravenna" loading="lazy"><img class="terra-couple" src="assets/daniele-laura.webp" alt="Daniele e Laura di Terra Latina" loading="lazy"></div>`:`<span class="tag">${esc(s.type)}</span>`}</div>`).join('');$('#passes').innerHTML=cfg.passes.map(p=>`<article class="pass ${esc(p.id)}"><span class="pass-name">${esc(p.name.toUpperCase())}</span><h3>${eur(p.price)} <small>/ persona</small></h3><p>${esc(p.desc)}</p><ul>${p.items.map(i=>`<li>${esc(i)}</li>`).join('')}</ul><button data-pass="${esc(p.id)}">Scelgo ${esc(p.name)} ↗</button></article>`).join('');$('#passSelect').innerHTML=cfg.passes.map(p=>`<option value="${esc(p.id)}">${esc(p.name)} · ${eur(p.price)}</option>`).join('');document.querySelectorAll('[data-pass]').forEach(b=>b.onclick=()=>{$('#passSelect').value=b.dataset.pass;update();$('#prenota').scrollIntoView({behavior:'smooth'})});update()}
function update(){const p=cfg.passes.find(p=>p.id===$('#passSelect').value);$('#total').textContent=eur(p.price*Number($('#qty').value||0));$('#workshops').innerHTML=p.stages.length?p.stages.map(id=>{const s=cfg.stages.find(s=>s.id===id);return s?`<label class="check"><input type="checkbox" name="workshop" value="${esc(id)}">${esc(s.title)}</label>`:''}).join(''):'<p style="font-size:12px;margin:0">Gli stage e la serata sono inclusi in entrambi gli ingressi.</p>'}
$('#passSelect').onchange=update;$('#qty').oninput=()=>{const p=cfg.passes.find(p=>p.id===$('#passSelect').value);$('#total').textContent=eur(p.price*Number($('#qty').value||0))};
let requestId=crypto.randomUUID();
$('#form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button[type=submit]');if(!ready||!cfg.open)return;const f=new FormData(e.target),p=cfg.passes.find(p=>p.id===f.get('pass'));button.disabled=true;$('#result').textContent='Invio della prenotazione…';try{const res=await fetch('/api/bookings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:requestId,name:f.get('name'),phone:f.get('phone'),pass:p.id,qty:Number(f.get('qty')),notes:f.get('notes'),workshops:f.getAll('workshop'),accepted:f.get('accepted')==='on',website:f.get('website'),revision,total_cents:Math.round(p.price*100)*Number(f.get('qty'))})});const data=await res.json();if(!res.ok)throw Error(data.error||'Invio non riuscito');$('#result').textContent=`Prenotazione confermata! Codice ${data.id.slice(0,8).toUpperCase()}. Totale ${eur(data.total_cents/100)} da pagare in loco. Conserva questo codice.`;requestId=crypto.randomUUID();e.target.reset();update()}catch(err){$('#result').textContent=err.message||'Connessione interrotta. Riprova: lo stesso invio non verrà duplicato.'}finally{button.disabled=!ready||!cfg.open}};
async function load(){render();$('#form').querySelector('button[type=submit]').disabled=true;try{const res=await fetch('/api/config',{cache:'no-store'});if(!res.ok)throw Error();const data=await res.json();cfg=data.config;revision=data.revision;ready=data.ready;render();$('#bookingNotice').textContent=ready?(cfg.open?'Prenotazioni aperte · Pagamento in loco':'Le prenotazioni sono momentaneamente chiuse.'):'Le prenotazioni saranno disponibili a breve.';$('#form').querySelector('button[type=submit]').disabled=!ready||!cfg.open}catch{$('#bookingNotice').textContent='Prenotazioni temporaneamente non disponibili. Riprova più tardi.'}}
load();
